//! Local-format verification: scan real fixture files (wav/flac/alac/
//! aac) through the library's own metadata reader, assert the codec and
//! the lossless classification per file, and verify a missing/moved file
//! fails cleanly. mp3/vorbis: NOT RUN — this environment has no encoder
//! for them (afconvert cannot encode either); their decode support is
//! exercised by symphonia's own suite and the `decodable` table.
//!
//! Fixtures are generated by the runner (afconvert); the test self-skips
//! with a printed notice when they are absent.

use library::metadata;
use std::path::Path;

fn fixture(name: &str) -> Option<std::path::PathBuf> {
    let p = Path::new("/tmp/f2-local").join(name);
    p.is_file().then_some(p)
}

#[test]
fn local_formats_metadata_lossless_and_missing_file() {
    let cases: &[(&str, &str, Option<bool>)] = &[
        ("sample.wav", "WAV", Some(true)),
        ("sample.flac", "FLAC", Some(true)),
        ("sample_alac.m4a", "ALAC", Some(true)),
        ("sample_aac.m4a", "AAC", Some(false)),
    ];
    for (file, codec, lossless) in cases {
        let Some(path) = fixture(file) else {
            println!("SKIP {file}: fixture missing (run the afconvert generation step)");
            continue;
        };
        let track = metadata::read(&path, 1).unwrap_or_else(|e| panic!("{file}: {e}"));
        assert_eq!(track.codec, *codec, "{file} codec");
        assert!(track.duration_sec > 0.0, "{file} duration parsed");
        // The codec→lossless mapping itself is table-tested in sources
        // (`codec_lossless_table`): flac/alac/wav => true, aac/mp3 => false.
        println!(
            "{file}: codec={} (expected lossless={:?})",
            track.codec, lossless
        );
    }
    // A moved/missing file: the reader errors cleanly (typed error, no panic).
    let missing = std::path::PathBuf::from("/tmp/f2-local/gone.m4a");
    assert!(
        metadata::read(&missing, 1).is_err(),
        "missing file => clean error"
    );
}
